Single-file change in client/src/store/project.js. Do not explore the repo, do not run eslint/vite/tests (the client toolchain is not needed), do not reformat unrelated code, do not touch any other file. Target: one focused edit pass.

WHY (verified in the current file): `project.$state.searchMentions` loops SEQUENTIALLY over `[project, ...getRelatedProjects(project)]` calling `searchProjectMentions(proj, ...)`, and `searchProjectFiles` expands `getRelatedProjects` AGAIN, so N sub-projects produce O(N^2) sequential `GET /api/files/search` round-trips per keystroke. The backend `search_files` already walks the active project root, which physically contains the sub-projects, so the nested expansion is pure duplication. `searchProjectMentions` also awaits `ensureFilesLoaded(project)` (`GET /api/knowledge/files`, the whole indexed file list) per project on every keystroke although that list is never used for ranking.

APPLY THESE EXACT EDITS (all inside client/src/store/project.js, top-level helpers first):

(A) After `getRelatedProjects(...)` add:
```js
const MENTION_SEARCH_CONCURRENCY = 3

const MENTION_FUSE_OPTIONS = {
  includeScore: true,
  minMatchCharLength: 3,
  keys: ["name", "searchIndex", "file"]
}

function isSameOrChildPath(parentPath, childPath) {
  if (!parentPath || !childPath) return false
  const normalizedParentPath = parentPath.endsWith('/') ? parentPath : `${parentPath}/`
  return childPath === parentPath || childPath.startsWith(normalizedParentPath)
}

/** Run `worker` over `items` with at most `limit` promises in flight. */
async function mapWithConcurrency(items, limit, worker) {
  const results = []
  let nextIndex = 0
  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (nextIndex < items.length) {
      const current = nextIndex++
      results[current] = await worker(items[current])
    }
  })
  await Promise.all(runners)
  return results
}

/**
 * Distinct roots a mention query has to search: the active project plus its
 * dependencies that live OUTSIDE its tree. Sub projects nested in the active
 * project root are dropped - the backend search already covers them.
 */
function getSearchRoots(project) {
  const candidates = [project, ...getRelatedProjects(project)]
    .filter(candidate => candidate && candidate.$api && candidate.abs_project_path)

  const roots = []
  for (const candidate of candidates) {
    const covered = roots.some(root => isSameOrChildPath(root.abs_project_path, candidate.abs_project_path))
    if (!covered) roots.push(candidate)
  }
  return roots
}
```

(B) Replace the whole body of `async function searchProjectFiles(project, searchQuery, limit = 20)` so it searches ONLY the project it receives (no `getRelatedProjects` expansion, no `allProjectsToSearch`). Keep the same result objects (`{ file, name, project, searchIndex }`), the same de-duplication by lowercase path, the same `$api.files.search({ search, pageSize: limit, page: 0 })` call, the same `console.error` on failure and `return fileResults.slice(0, limit)`.

(C) Replace `async function searchProjectMentions(project, query, limit, controller)` with a version that takes `onResults` and fans out once:
```js
async function searchProjectMentions(project, query, limit, controller, onResults) {
  await ensureProfilesLoaded(project)

  controller.checkCancelled()
  controller.setProgress({ stage: 'loading', project: project.project_name })

  const combined = await buildMentions(project)
  controller.checkCancelled()

  const rank = () => new Fuse(combined, MENTION_FUSE_OPTIONS)
    .search(query)
    .map(result => ({ ...result.item, score: result.score }))
    .filter(({ score }) => score < 0.25)
    .slice(0, limit)

  if (!query || query.length < 2) {
    return rank()
  }

  const seenFiles = new Set()

  await mapWithConcurrency(getSearchRoots(project), MENTION_SEARCH_CONCURRENCY, async searchRoot => {
    const fileResults = await searchProjectFiles(searchRoot, query, limit)
    controller.checkCancelled()

    for (const fileResult of fileResults) {
      const key = (fileResult.file || fileResult.name).toLowerCase()
      if (seenFiles.has(key)) continue
      seenFiles.add(key)
      combined.push({
        name: fileResult.name,
        file: fileResult.file,
        project: fileResult.project,
        searchIndex: fileResult.searchIndex,
        avatar: fileResult.project?.project_icon,
        mention: encodeURIComponent(fileResult.name)
      })
    }

    if (onResults) onResults(rank())
  })

  controller.checkCancelled()
  return rank()
}
```

(D) Inside `initProject`, replace the body of `project.$state.searchMentions = async function({ query, limit = 10, onResults, controller })` (currently the sequential `for (const proj of allProjectsToSearch)` loop) with:
```js
    project.$state.searchMentions = async function({ query, limit = 10, onResults, controller }) {
      try {
        controller.isSearching = true
        return await searchProjectMentions(project, query, limit, controller, onResults)
      } catch (error) {
        if (error.message !== 'Search cancelled') {
          console.error('Error searching mentions:', error)
        }
        return []
      } finally {
        controller.isSearching = false
      }
    }
```
Keep the exported action `searchMentions({ query, limit = 10, onResults, controller })` signature untouched (it delegates to `project.$state.searchMentions`).

(E) Rewrite the store action `reloadMentions({ state })` to use the distinct roots and bounded concurrency: `const searchRoots = getSearchRoots(project); searchRoots.forEach(clearMentionCache); await mapWithConcurrency(searchRoots, MENTION_SEARCH_CONCURRENCY, p => ensureProfilesLoaded(p, true))`. Do NOT call `ensureFilesLoaded` from the mention path any more (keep the helper itself: `initProject` still uses it).

CONSTRAINTS: keep `buildMentions`, `ensureFilesLoaded`, `ensureProfilesLoaded`, `clearMentionCache`, `getProjectDependencies`, `getRelatedProjects` as they are (only add the new helpers); keep the suggestion payload keys `{ name, file, project, searchIndex, avatar, mention, score }`; keep plain JS style of the file; no unrelated reformatting.

VERIFY: re-read the edited regions and state in your report the 5 edit points, that `searchProjectFiles` no longer references `getRelatedProjects`, and that `ensureFilesLoaded` is no longer called from the mention search. Do not run the client build.

**Acceptance criteria**
Diff in client/src/store/project.js shows: `searchProjectFiles` searches only its argument; `searchProjectMentions` fans out once over `getSearchRoots(project)` with `mapWithConcurrency` (max 3), merges de-duplicated file results into the mention list and ranks once with the existing Fuse options plus the `score < 0.25` + `limit` filter; `$state.searchMentions` delegates with try/catch/finally and calls `onResults`; `reloadMentions` uses the same distinct roots and no longer calls `ensureFilesLoaded`; payload keys unchanged.

